import{_ as o,o as e,c as a,a2 as u}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1985年 · 烂生意的教训","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1985年.md","filePath":"05_quotes/by-year/1985年.md"}'),r={name:"05_quotes/by-year/1985年.md"};function q(l,t,s,c,p,b){return e(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1985年-·-烂生意的教训" tabindex="-1">1985年 · 烂生意的教训 <a class="header-anchor" href="#_1985年-·-烂生意的教训" aria-label="Permalink to &quot;1985年 · 烂生意的教训&quot;">​</a></h1><blockquote><p>&quot;好管理记录（按经济回报衡量），很大程度你拿到什么business船，比你划船多有效影响更大。有些船天生漏水比别的多，你换不了船，你能做就是调整漏水速度。&quot;——巴菲特（55岁）</p></blockquote><p>本页收录1985年致股东信中的经典语录。巴菲特在这一年坦诚关闭了持续二十年的纺织业务，系统反思了&quot;烟蒂投资法&quot;的局限，并深刻批判了股权激励的痼疾。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;当你发现自己在漏水的船，你换船比你堵漏洞划算多了。&quot;</p></blockquote><blockquote><p>&quot;我在错的business，再多聪明努力也没用。你换不了船，你能做就是调整漏水速度。&quot;</p></blockquote><blockquote><p>&quot;有些投资者买股票看重账面价值，相信重置价值，你看我们卖掉纺织设备，原来花1300万，现在账面价值86.6万，卖掉设备总proceeds才16.3万美元，相当于全新买要三到五千万，现在一块钱都不值。所以，通货膨胀时代，有形资产多的企业，股东回报不一定涨。&quot;</p></blockquote><blockquote><p>&quot;很多公司股权激励计划，奖励就是留存盈利复利带来的盈利增长，完全不用动脑筋，就像你存银行，利息不拿出来，十年后利息翻倍，经理拿奖励，这不公平。&quot;</p></blockquote><blockquote><p>&quot;期权要合理定价，价格压低就是把部分business价值便宜卖给insider，无论卖给insider还是outsider，低于business价值卖都是对现有股东伤害。&quot;</p></blockquote><blockquote><p>&quot;期权应该和公司整体表现绑定，逻辑上，只有对整体负责的经理才能给期权，有限责任经理应该拿和他们责任范围对应的激励。你做不到你责任你不该拿奖励，0.150打席就应该拿0.150奖励，哪怕球队赢了。&quot;</p></blockquote><blockquote><p>&quot;我们伯克希尔激励体系，关键经理达到自己领域目标就奖励。喜诗糖果做好了，不会给水牛城新闻激励，反过来也一样。平均绩效拿不到奖金，出色绩效能拿很多，小单位经理也能拿比大单位多，只要结果好。&quot;</p></blockquote><blockquote><p>&quot;伯克希尔过去历史，留存盈利回报率一直超过市场，每一美元留存创造超过一美元市场价值，这种情况下，任何分红都违背股东利益，如果我们分了，我们现在肯定小很多。&quot;</p></blockquote><blockquote><p>&quot;好管理层在烂生意上，就像好司机开好车，但是烂路怎么开都快不了。&quot;</p></blockquote><blockquote><p>&quot;很多企业总有一天，只要条件合适，都应该关门，因为继续耗下去，股东亏得更多。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1985年伯克希尔净值增长6.136亿美元，增幅48.2%，是历史最高增速之一。巴菲特在七月关闭了纺织业务，终结了长达二十年的错误。查理·芒格以172.50美元买入了首都城市/ABC的300万股，汤姆·墨斐和丹·伯克的管理能力令巴菲特折服。同年还收购了Scott &amp; Fetzer，认识了传奇CEO拉尔夫·谢伊。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1985年/翻译.html">01_letters/1985年/翻译</a> · <a href="/01_letters/1985年/核心总结.html">01_letters/1985年/核心总结</a> · <a href="/01_letters/1985年/思维导图.html">01_letters/1985年/思维导图</a></p>',21)])])}const _=o(r,[["render",q]]);export{n as __pageData,_ as default};
